/* TV login: D-pad focus is navigation only; OK activates editing. */
(function(){
 if(!document.documentElement.classList.contains("swoop-android-tv"))return;
 const ids=["server","username","password"];
 function lockLogin(){
  if(!document.getElementById("xtreamform"))return;
  for(const id of ids){const input=document.getElementById(id);if(input&&input!==document.activeElement)input.readOnly=true}
 }
 document.addEventListener("focusin",e=>{
  if(!ids.includes(e.target.id)||!document.getElementById("xtreamform"))return;
  if(e.target.dataset.tvEditing!=="1")e.target.readOnly=true;
 });
 document.addEventListener("focusout",e=>{
  if(!ids.includes(e.target.id))return;
  e.target.readOnly=true;delete e.target.dataset.tvEditing;
 });
 document.addEventListener("keydown",e=>{
  if(!ids.includes(e.target.id)||!document.getElementById("xtreamform"))return;
  if((e.key==="Enter"||e.key==="NumpadEnter")&&e.target.readOnly){
   e.preventDefault();e.stopImmediatePropagation();
   e.target.dataset.tvEditing="1";e.target.readOnly=false;
   e.target.click();
  }
 },true);
 const observer=new MutationObserver(lockLogin);
 observer.observe(document.getElementById("app"),{childList:true});
 lockLogin();
 requestAnimationFrame(()=>{
  const first=document.getElementById("server");
  if(first){first.readOnly=true;first.focus({preventScroll:true})}
 });
})();
/* Directional remote focus for the native Android TV WebView. */
(function(){
 if(!document.documentElement.classList.contains("swoop-android-tv"))return;
 const selector='button:not([disabled]):not([hidden]),a[href],input:not([disabled]),select:not([disabled]),[tabindex]:not([tabindex="-1"])';
 const eligible=el=>{if(!el||!el.isConnected)return false;const r=el.getBoundingClientRect(),style=getComputedStyle(el);return r.width>2&&r.height>2&&style.visibility!=="hidden"&&style.display!=="none"};
 const candidates=()=>Array.from(document.querySelectorAll(selector)).filter(eligible);
 let lastKey="";
 function move(key){const items=candidates();if(!items.length)return;const active=document.activeElement;const from=items.includes(active)?active:null;const onHome=page==="Home"&&!homeSearchOpen;const navButton=active?.closest?.("#topnav");if(onHome&&key==="ArrowDown"&&navButton){const search=document.getElementById("home-search-open");if(search){search.focus({preventScroll:true});search.scrollIntoView({block:"nearest",inline:"nearest"});return}}if(onHome&&key==="ArrowUp"&&active?.id==="home-search-open"){const target=document.querySelector("#topnav button.active")||document.querySelector("#topnav button");if(target){target.focus({preventScroll:true});window.scrollTo({top:0,behavior:"instant"});return}}if(!from){(document.querySelector('#topnav button.active')||items[0]).focus({preventScroll:true});return}
 const a=active.getBoundingClientRect(),ax=(a.left+a.right)/2,ay=(a.top+a.bottom)/2;
 let best=null,score=Infinity;
 for(const el of items){if(el===active)continue;const r=el.getBoundingClientRect(),x=(r.left+r.right)/2,y=(r.top+r.bottom)/2,dx=x-ax,dy=y-ay;
 const primary=key==="ArrowRight"?dx:key==="ArrowLeft"?-dx:key==="ArrowDown"?dy:-dy;
 if(primary<4)continue;
 const cross=key==="ArrowRight"||key==="ArrowLeft"?Math.abs(dy):Math.abs(dx);
 const s=primary+cross*2.8+(cross>Math.max(a.width,a.height)*1.3?cross:0);
 if(s<score){score=s;best=el}}
 if(!best&&key==="ArrowUp"){best=document.querySelector("#topnav button.active")||document.querySelector("#topnav button");if(best)window.scrollTo({top:0,behavior:"instant"})}if(best){best.focus({preventScroll:true});best.scrollIntoView({block:"nearest",inline:"nearest",behavior:"instant"})}
 }
 document.addEventListener("keydown",e=>{if(!["ArrowUp","ArrowDown","ArrowLeft","ArrowRight"].includes(e.key))return;if(e.target.matches('input,textarea,select')&&e.key!=="ArrowDown"&&e.key!=="ArrowUp")return;e.preventDefault();lastKey=e.key;move(e.key)},true);
 document.addEventListener("focusin",e=>{if(e.target.matches(selector))e.target.classList.add("tv-focused")});
 document.addEventListener("focusout",e=>e.target.classList?.remove("tv-focused"));
 let loginFocusSet=false;
 function focusLoginFirst(){
  const server=document.querySelector("#xtreamform #server");
  if(!server){loginFocusSet=false;return}
  if(loginFocusSet)return;
  loginFocusSet=true;
  server.readOnly=true;
  server.focus({preventScroll:true});
 }
 const observer=new MutationObserver(()=>{if(document.querySelector("#xtreamform")){focusLoginFirst();return}if(document.activeElement===document.body&&document.querySelector("#app button")){const target=document.querySelector('#topnav button.active')||document.querySelector('#app button');if(target)target.focus({preventScroll:true})}});
 observer.observe(document.getElementById("app"),{childList:true});
 requestAnimationFrame(()=>{if(document.querySelector("#xtreamform")){focusLoginFirst();return}const target=document.querySelector('#topnav button.active')||document.querySelector('#app button');if(target)target.focus({preventScroll:true})});
})();
